<?php
namespace App\Models;
use App\Core\Model;
final class Analytics extends Model {
 public function coverage(int $days=30):array{return $this->all("SELECT p.id,p.name,p.internal_code,s.quantity,s.reserved_quantity,p.min_stock,p.max_stock,COALESCE(v.avg_daily,0) avg_daily,CASE WHEN COALESCE(v.avg_daily,0)>0 THEN (s.quantity-s.reserved_quantity)/v.avg_daily ELSE NULL END coverage_days,CASE WHEN COALESCE(v.avg_daily,0)>0 THEN GREATEST(0,CEIL((p.max_stock + v.avg_daily*COALESCE(sp.lead_time_days,3))-(s.quantity-s.reserved_quantity))) ELSE GREATEST(0,p.max_stock-(s.quantity-s.reserved_quantity)) END recommended_qty FROM products p JOIN stocks s ON s.product_id=p.id LEFT JOIN suppliers sp ON sp.id=p.supplier_id LEFT JOIN (SELECT si.product_id,SUM(si.quantity)/? avg_daily FROM sale_items si JOIN sales sa ON sa.id=si.sale_id WHERE sa.status='COMPLETED' AND sa.created_at>=DATE_SUB(NOW(),INTERVAL ? DAY) GROUP BY si.product_id) v ON v.product_id=p.id WHERE p.status='ACTIVE' ORDER BY coverage_days IS NULL,coverage_days ASC LIMIT 100",[$days,$days]);}
 public function stars():array{return $this->all("SELECT p.name,SUM(si.quantity) qty,SUM(si.subtotal) revenue,SUM((si.unit_price-si.purchase_price)*si.quantity) margin FROM sale_items si JOIN sales s ON s.id=si.sale_id JOIN products p ON p.id=si.product_id WHERE s.status='COMPLETED' GROUP BY p.id,p.name ORDER BY qty DESC LIMIT 10");}
 public function dormant(int $days=30):array{return $this->all("SELECT p.id,p.name,s.quantity,MAX(sa.created_at) last_sale FROM products p JOIN stocks s ON s.product_id=p.id LEFT JOIN sale_items si ON si.product_id=p.id LEFT JOIN sales sa ON sa.id=si.sale_id AND sa.status='COMPLETED' WHERE p.status='ACTIVE' GROUP BY p.id,p.name,s.quantity HAVING last_sale IS NULL OR last_sale<DATE_SUB(NOW(),INTERVAL ? DAY) ORDER BY last_sale IS NULL DESC,last_sale ASC LIMIT 100",[$days]);}
 public function segments():array{return $this->all("SELECT c.id,c.code,CONCAT(c.first_name,' ',c.last_name) customer,c.total_spent,c.order_count,MAX(s.created_at) last_purchase,CASE WHEN c.order_count=0 THEN 'NOUVEAU' WHEN MAX(s.created_at)<DATE_SUB(NOW(),INTERVAL 60 DAY) THEN 'INACTIF' WHEN c.total_spent>=500 OR c.order_count>=20 THEN 'VIP' WHEN c.total_spent>=200 OR c.order_count>=10 THEN 'FIDELE' ELSE 'REGULIER' END computed_segment FROM customers c LEFT JOIN sales s ON s.customer_id=c.id AND s.status='COMPLETED' GROUP BY c.id ORDER BY c.total_spent DESC");}
}
